            document.getElementById('yue-lingshuang-thought').innerText = getLatestThought('岳凌霜.内心想法');
            document.getElementById('yun-xiyue-thought').innerText = getLatestThought('云曦月.内心想法');
            document.getElementById('qin-wanrou-thought').innerText = getLatestThought('秦婉柔.内心想法');
            document.getElementById('su-qinghan-thought').innerText = getLatestThought('苏清寒.内心想法');
            document.getElementById('liu-hanyan-thought').innerText = getLatestThought('柳含烟.内心想法');
            document.getElementById('lin-chuxue-thought').innerText = getLatestThought('林初雪.内心想法');
            document.getElementById('xia-yubing-thought').innerText = getLatestThought('夏语冰.内心想法');

