                let thought = SafeGetValue(characterData, path);
                const thoughtParts = thought.split('->');
                thought = thoughtParts.length > 1 ? thoughtParts[1].trim() : thoughtParts[0].trim();
                const noteMatch = thought.match(/【.*?】/);
                if (noteMatch) {
                    thought = thought.replace(noteMatch[0], '').trim();
                }
                return thought;
            }

            document.getElementById('world-current-time').innerText = getLatestThought('世界.当前时刻');
            document.getElementById('world-current-location').innerText = getLatestThought('世界.当前地点');

            updateProgressBar('world-qingxingdu-bar', 'world-qingxingdu', 'world-qingxingdu-desc', SafeGetValue(characterData, '世界.清醒度'), 0, 100, 'var(--accent-cyan)');

            document.getElementById('yue-lingshuang-thought').innerText = getLatestThought('岳凌霜.内心想法');
            document.getElementById('yun-xiyue-thought').innerText = getLatestThought('云曦月.内心想法');
            document.getElementById('qin-wanrou-thought').innerText = getLatestThought('秦婉柔.内心想法');
            document.getElementById('su-qinghan-thought').innerText = getLatestThought('苏清寒.内心想法');
            document.getElementById('liu-hanyan-thought').innerText = getLatestThought('柳含烟.内心想法');
            document.getElementById('lin-chuxue-thought').innerText = getLatestThought('林初雪.内心想法');
            document.getElementById('xia-yubing-thought').innerText = getLatestThought('夏语冰.内心想法');

            updateProgressBar('shen-xiuyan-qiyun-bar', 'shen-xiuyan-qiyun', 'shen-xiuyan-qiyun-desc', SafeGetValue(characterData, '沈修言.气运'), 0, 100, 'var(--accent-gold)');

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
